-- ============================================================================
-- seed_demo_projects.sql
--
-- What it seeds:
--   • Upserts the super-admin central_users + tenant_membership row
--   • Ensures the super-admin has a workspace object_membership
--   • Creates 1 demo organization
--   • Creates 3 demo projects (each with):
--       - object_membership (owner)
--       - project_valuation
--       - fund (Collaboration Fund, status = active)
--       - fund_valuation
--       - contract (contributor agreement)
--       - project_brief note + project_notes link
--       - semantic_document
--       - wallet_account (if missing)
--       - 3 objectives, each with:
--           · objective_note + objective_notes link
--           · assignment (fund_linked credits)
--           · contract_acceptance
--           · assignment_term_acceptance
--           · reward_issuance
--           · wallet_ledger entry (creator_earn)
--       - participant_position (aggregate credits)
--
-- Fixed IDs (must already exist before running):
--   auth_user_id / owner_central_id : ce8bbd89-dea9-4ae2-b6c4-2b9ca15b064f
--   tenant_id                        : 30a00e60-7cae-4a5e-a311-b3be998e7113
--   workspace_id                     : 1ff27174-014a-4ee0-b3b0-e17521d3c07c
--
-- Enum corrections vs original draft:
--   - value_mode: 'fixed' → 'cumulative' (valid: cumulative, divided)
--   - assignment value_type: 'fixed' → 'fund_linked' (valid: fund_linked, informational)
--   - wallet_ledger entry_type: 'reward_issuance' → 'creator_earn'
--     (valid: stripe_topup, chat_spend, bundle_purchase, platform_fee,
--             creator_earn, withdrawal, transfer)
-- ============================================================================

do $$
declare
  v_auth_email         text := 'dev-superadmin@xcamp.local';
  v_auth_user_id       uuid := 'ce8bbd89-dea9-4ae2-b6c4-2b9ca15b064f';
  v_tenant_id          uuid := '30a00e60-7cae-4a5e-a311-b3be998e7113';
  v_workspace_id       uuid := '1ff27174-014a-4ee0-b3b0-e17521d3c07c';

  v_owner_id           uuid;
  v_org_id             uuid;
  v_project_id         uuid;
  v_objective_id       uuid;
  v_note_id            uuid;
  v_fund_id            uuid;
  v_contract_id        uuid;
  v_assignment_id      uuid;
  v_reward_issuance_id uuid;
  p                    record;
  o                    record;
begin

  -- ── 1. Pre-flight validations ─────────────────────────────────────────────

  if not exists (
    select 1 from auth.users
    where id = v_auth_user_id and email = v_auth_email
  ) then
    raise exception
      'Expected auth user not found. id=%, email=%', v_auth_user_id, v_auth_email;
  end if;

  if not exists (
    select 1 from public.tenants
    where id = v_tenant_id and status = 'active'
  ) then
    raise exception
      'Expected active tenant not found. tenant_id=%', v_tenant_id;
  end if;

  if not exists (
    select 1 from public.workspaces
    where id = v_workspace_id
      and tenant_id = v_tenant_id
      and deleted_at is null
  ) then
    raise exception
      'Expected active workspace not found. workspace_id=%, tenant_id=%',
      v_workspace_id, v_tenant_id;
  end if;

  -- ── 2. central_users upsert ───────────────────────────────────────────────

  insert into public.central_users (id, email, tenant_id, preferences)
  values (
    v_auth_user_id,
    v_auth_email,
    v_tenant_id,
    jsonb_build_object(
      'seeded_demo_admin', true,
      'active_demo_workspace_id', v_workspace_id
    )
  )
  on conflict (id) do update
    set email      = excluded.email,
        updated_at = now();

  v_owner_id := v_auth_user_id;

  -- ── 3. tenant_memberships upsert ──────────────────────────────────────────

  insert into public.tenant_memberships
    (tenant_id, user_id, role, status, joined_at, metadata)
  values (
    v_tenant_id, v_owner_id, 'super_admin', 'active', now(),
    jsonb_build_object('source', 'seed_demo_projects')
  )
  on conflict (tenant_id, user_id) do update
    set role   = excluded.role,
        status = 'active';

  -- ── 4. workspace object_membership ───────────────────────────────────────

  insert into public.object_memberships
    (object_type, object_id, user_central_id, role, status,
     invited_by, joined_at, tenant_id)
  values
    ('workspace', v_workspace_id, v_owner_id, 'owner', 'active',
     v_owner_id, now(), v_tenant_id)
  on conflict (object_type, object_id, user_central_id)
    do update set role = excluded.role, status = 'active';

  -- ── 5. wallet_account ────────────────────────────────────────────────────

  insert into public.wallet_accounts (central_user_id, tenant_id)
  values (v_owner_id, v_tenant_id)
  on conflict (central_user_id) do nothing;

  -- ── 6. Organization ──────────────────────────────────────────────────────

  insert into public.organizations
    (name, owner_central_id, tenant_id)
  values
    ('Xchange Demo Organization', v_owner_id, v_tenant_id)
  returning id into v_org_id;

  insert into public.object_memberships
    (object_type, object_id, user_central_id, role, status,
     invited_by, joined_at, tenant_id)
  values
    ('organization', v_org_id, v_owner_id, 'owner', 'active',
     v_owner_id, now(), v_tenant_id)
  on conflict (object_type, object_id, user_central_id) do nothing;

  -- ── 7. Projects loop ─────────────────────────────────────────────────────

  for p in
    select *
    from (values
      (
        'Regenerative Fashion Marketplace',
        'A project to build a credit-based marketplace for regenerative fashion producers, circular materials, and local designers.',
        '🌱', '#22c55e', 120000::numeric
      ),
      (
        'AI Mentor for Startup Founders',
        'A multi-agent mentoring system that helps early-stage founders clarify strategy, milestones, investor readiness, and execution priorities.',
        '🧭', '#6366f1', 250000::numeric
      ),
      (
        'Community Energy Transition Fund',
        'A participatory project for funding local renewable energy initiatives, community ownership, and transparent contribution rewards.',
        '⚡', '#f59e0b', 500000::numeric
      )
    ) as t(title, description, icon, color, project_value)
  loop

    -- 7a. Project
    insert into public.projects
      (owner_central_id, title, description, color, icon, status,
       organization_id, visibility_scope, tenant_id)
    values
      (v_owner_id, p.title, p.description, p.color, p.icon, 'active',
       v_org_id, 'organization_only', v_tenant_id)
    returning id into v_project_id;

    -- 7b. Project object_membership
    insert into public.object_memberships
      (object_type, object_id, user_central_id, role, status,
       invited_by, joined_at, tenant_id)
    values
      ('project', v_project_id, v_owner_id, 'owner', 'active',
       v_owner_id, now(), v_tenant_id)
    on conflict (object_type, object_id, user_central_id) do nothing;

    -- 7c. Project valuation
    insert into public.project_valuations
      (init_id, project_value_reference, valuation_source_type,
       notes, created_by, tenant_id)
    values
      (v_project_id, p.project_value, 'seed_demo',
       'Initial seeded reference valuation.', v_owner_id, v_tenant_id);

    -- 7d. Fund
    insert into public.funds
      (project_id, name, description, fund_type, status,
       reserved_value_percent, is_default, is_transferable,
       transferability_rules, vesting_rules, redemption_rules,
       created_by, tenant_id)
    values
      (v_project_id, 'Collaboration Fund',
       'Default collaboration fund for demo assignments and rewards.',
       'collaboration', 'active',
       15, true, true,
       '{}'::jsonb, '{}'::jsonb, '{}'::jsonb,
       v_owner_id, v_tenant_id)
    returning id into v_fund_id;

    -- 7e. Fund valuation
    insert into public.fund_valuations
      (fund_id, project_value_ref, fund_value_total, active_credit_supply,
       value_per_credit, snapshot_reason, created_by, tenant_id)
    values
      (v_fund_id, p.project_value, p.project_value * 0.15, 10000,
       round((p.project_value * 0.15) / 10000, 4),
       'Initial seeded fund valuation.', v_owner_id, v_tenant_id);

    -- 7f. Contract
    insert into public.contracts
      (init_id, version, title, contract_text, is_active, created_by,
       fund_id, tenant_id)
    values
      (v_project_id, 1, p.title || ' Contributor Agreement',
       'Seeded demo contributor agreement.', true, v_owner_id,
       v_fund_id, v_tenant_id)
    returning id into v_contract_id;

    -- 7g. Project brief note
    insert into public.notes
      (owner_central_id, note_type, title, body_markdown, body_text,
       body_html, visibility, visibility_scope, tenant_id)
    values
      (v_owner_id, 'project_brief',
       p.title || ' — Project Brief',
       '# ' || p.title || E'\n\n' || p.description,
       p.description,
       '<p>' || p.description || '</p>',
       'public', 'organization_only', v_tenant_id)
    returning id into v_note_id;

    -- 7h. project_notes link
    insert into public.project_notes
      (owner_central_id, project_id, note_id, role, tenant_id)
    values
      (v_owner_id, v_project_id, v_note_id, 'brief', v_tenant_id)
    on conflict (owner_central_id, project_id, note_id) do nothing;

    -- 7i. Semantic document
    insert into public.semantic_documents
      (tenant_id, workspace_id, entity_type, entity_id, title, content,
       metadata, semantic_tags, is_indexed)
    values
      (v_tenant_id, v_workspace_id, 'project', v_project_id, p.title,
       p.description,
       jsonb_build_object(
         'source', 'seed_demo_projects',
         'project_title', p.title
       ),
       array['demo', 'project', 'xcamp'],
       false);

    -- ── 8. Objectives loop ───────────────────────────────────────────────────

    for o in
      select *
      from (values
        (
          'Define strategy and success metrics',
          'Clarify the project thesis, target users, measurable outcomes, and near-term execution milestones.',
          3000::numeric
        ),
        (
          'Build first operational prototype',
          'Create a usable prototype that demonstrates the core workflow and validates the project logic.',
          4500::numeric
        ),
        (
          'Activate contributors and reward flow',
          'Invite first contributors, define assignments, and connect verified work to collaboration credits.',
          2500::numeric
        )
      ) as t(title, description, credit_value)
    loop

      -- 8a. Objective
      -- value_mode valid values: cumulative, divided
      insert into public.objectives
        (project_id, owner_central_id, title, description, dimension,
         category, status, credit_value, sort_order, visibility_scope,
         value_mode, objective_total_value, tenant_id)
      values
        (v_project_id, v_owner_id, o.title, o.description, 'execution',
         'demo', 'active', o.credit_value, 1, 'project_only',
         'cumulative', o.credit_value, v_tenant_id)
      returning id into v_objective_id;

      -- 8b. Objective note
      insert into public.notes
        (owner_central_id, note_type, title, body_markdown, body_text,
         body_html, visibility, visibility_scope, tenant_id)
      values
        (v_owner_id, 'objective_note',
         o.title,
         '# ' || o.title || E'\n\n' || o.description,
         o.description,
         '<p>' || o.description || '</p>',
         'public', 'project_only', v_tenant_id)
      returning id into v_note_id;

      -- 8c. objective_notes link
      insert into public.objective_notes
        (objective_id, note_id, owner_central_id, tenant_id)
      values
        (v_objective_id, v_note_id, v_owner_id, v_tenant_id)
      on conflict (objective_id, note_id) do nothing;

      -- 8d. Assignment
      -- value_type valid values: fund_linked, informational
      insert into public.assignments
        (object_type, object_id, init_id, user_id, invited_by,
         proposed_value, currency_type, value_type, contract_id,
         contract_version, fund_id, tenant_id)
      values
        ('objective', v_objective_id, v_project_id, v_owner_id, v_owner_id,
         o.credit_value, 'credits', 'fund_linked', v_contract_id, 1,
         v_fund_id, v_tenant_id)
      returning id into v_assignment_id;

      -- 8e. Contract acceptance (no unique constraint — plain INSERT)
      insert into public.contract_acceptances
        (assignment_id, user_id, contract_id, contract_version,
         contract_snapshot, fund_id, fund_terms_version,
         fund_terms_snapshot, tenant_id)
      values
        (v_assignment_id, v_owner_id, v_contract_id, 1,
         'Seeded demo acceptance.', v_fund_id, 1,
         'Seeded demo fund terms.', v_tenant_id);

      -- 8f. Assignment term acceptance
      insert into public.assignment_term_acceptances
        (assignment_id, fund_id, user_id, fund_terms_version,
         fund_terms_snapshot, tenant_id)
      values
        (v_assignment_id, v_fund_id, v_owner_id, 1,
         jsonb_build_object(
           'source', 'seed_demo_projects',
           'credit_value', o.credit_value
         ),
         v_tenant_id)
      on conflict (assignment_id, user_id) do nothing;

      -- 8g. Reward issuance
      insert into public.reward_issuances
        (fund_id, assignment_id, user_id, credit_amount, reason,
         issued_by, tenant_id)
      values
        (v_fund_id, v_assignment_id, v_owner_id, o.credit_value,
         'Seeded reward issuance.', v_owner_id, v_tenant_id)
      returning id into v_reward_issuance_id;

      -- 8h. Wallet ledger entry
      -- entry_type valid values: stripe_topup, chat_spend, bundle_purchase,
      --   platform_fee, creator_earn, withdrawal, transfer
      insert into public.wallet_ledger
        (account_central_user_id, entry_type, amount_credits, payable,
         project_id, objective_id, fund_id, issuance_id, credit_status,
         metadata, tenant_id)
      values
        (v_owner_id, 'creator_earn', o.credit_value::integer, true,
         v_project_id, v_objective_id, v_fund_id, v_reward_issuance_id,
         'open',
         jsonb_build_object(
           'source',          'seed_demo_projects',
           'project_title',   p.title,
           'objective_title', o.title
         ),
         v_tenant_id);

    end loop; -- objectives

    -- 8i. Participant position
    insert into public.participant_positions
      (fund_id, user_id, credits_earned, credits_active, credits_sold,
       credits_redeemed, credits_locked, status, init_id, tenant_id)
    values
      (v_fund_id, v_owner_id, 10000, 10000, 0, 0, 0, 'active',
       v_project_id, v_tenant_id)
    on conflict (fund_id, user_id) do update
      set credits_earned = excluded.credits_earned,
          credits_active = excluded.credits_active,
          status         = 'active';

  end loop; -- projects

  raise notice
    'seed_demo_projects: seeded into tenant=%, workspace=%, owner=%',
    v_tenant_id, v_workspace_id, v_owner_id;

end $$;
